import json, sys
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot
r=Robot(); s=r.spec(); print(json.dumps({k:s.get(k) for k in ['protocol','static','world','robot_spec','proprio_layout','proprio_groups','default_cameras','action_types','budget','max_call_wall_s','control_hz']}, indent=2)[:18000]); print('STATUS',r.status())
o=r.get_obs(depth=True,video='none'); print('META',json.dumps(o.meta,indent=2)[:6000]);
from PIL import Image
for c,a in o.last.items(): Image.fromarray(a).save('/app/output/init_'+c+'.png')
for c,a in o.last_depth.items(): print('DEPTH',c,a.shape,float(a.min()),float(a.max()))
